-- Mega Evolution promos only
alter table public.master_set_catalog drop constraint if exists master_set_catalog_set_id_check;
alter table public.master_set_catalog add constraint master_set_catalog_set_id_check check (set_id in ('me01','me02','me02.5','me03','me04','me05','mep'));

on conflict (set_id, card_id, variant) do update set card_number = excluded.card_number, card_name = excluded.card_name, image_url = excluded.image_url, rarity = excluded.rarity, sort_order = excluded.sort_order;

